  const deck=new THREE.Group();this.physical.add(deck);const base=box(5.5,.24,3.35,'#243645',.44,.52);base.position.y=-.13;deck.add(base);const top=box(5.36,.075,3.22,'#536777',.62,.35);top.position.y=.025;deck.add(top);const inset=box(5.04,.025,2.86,'#182a39',.4,.36);inset.position.set(0,.074,0);deck.add(inset);
