  for(const z of [-1.36,1.36]){const beam=box(4.64,.12,.12,'#1d2d39',.42,.62);beam.position.set(0,-.35,z);deck.add(beam);}
  for(const x of [-2.55,2.55]){const rail=box(.075,.045,2.95,'#a9a18f',.32,.68);rail.position.set(x,.1,0);deck.add(rail);for(const z of [-1.35,1.35]){const screw=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,.018,16),new THREE.MeshStandardMaterial({color:'#c0b79f',metalness:.8,roughness:.28}));screw.position.set(x,.125,z);deck.add(screw);}}
  const titlePlate=new THREE.Mesh(new THREE.PlaneGeometry(2.8,.36),new THREE.MeshBasicMaterial({map:labelTexture('OUTPOST CONTROL · MISSION TABLE',true),toneMapped:false}));titlePlate.rotation.x=-Math.PI/2;titlePlate.position.set(0,.092,1.25);deck.add(titlePlate);
  const terrain=new THREE.Mesh(new THREE.PlaneGeometry(3.5,1.55,42,24),new THREE.MeshStandardMaterial({color:'#9b907d',roughness:.98,metalness:.02,side:THREE.DoubleSide}));terrain.rotation.x=-Math.PI/2;terrain.position.set(-.62,.095,-.03);const pos=terrain.geometry.attributes.position;for(let i=0;i<pos.count;i++){const x=pos.getX(i),y=pos.getY(i);pos.setZ(i,.075*Math.sin(x*4.2)*Math.cos(y*3.8)+.025*Math.cos(x*11+y*6));}terrain.geometry.computeVertexNormals();deck.add(terrain);
  const sites=getLunarSiteCandidates().records;sites.slice(0,3).forEach((_,i)=>{const x=-1.65+i*1.04,z=.42+(i===1?-.12:.12);const pad=new THREE.Mesh(new THREE.CylinderGeometry(.34,.39,.09,40),new THREE.MeshStandardMaterial({color:'#b4a78c',roughness:.72,metalness:.12,emissive:'#c19442',emissiveIntensity:.06}));pad.position.set(x,.16,z);pad.userData.kind='site';pad.userData.index=i;deck.add(pad);const ring=new THREE.Mesh(new THREE.TorusGeometry(.36,.018,8,48),new THREE.MeshStandardMaterial({color:'#9caeb7',metalness:.6,roughness:.35,emissive:'#88c6da',emissiveIntensity:.08}));ring.rotation.x=Math.PI/2;ring.position.set(x,.22,z);ring.userData.kind='site';ring.userData.index=i;deck.add(ring);const marker=new THREE.Mesh(new THREE.ConeGeometry(.075,.2,5),new THREE.MeshStandardMaterial({color:'#d9bd81',metalness:.35,roughness:.42}));marker.position.set(x,.28,z);marker.rotation.x=Math.PI;marker.userData.kind='site';marker.userData.index=i;deck.add(marker);const plaque=new THREE.Mesh(new THREE.PlaneGeometry(.78,.2),new THREE.MeshBasicMaterial({map:labelTexture(`${i+1} · CANDIDATE SITE`,true),toneMapped:false,side:THREE.DoubleSide}));plaque.rotation.x=-Math.PI/2;plaque.position.set(x,.14,z+.48);deck.add(plaque);this.siteMeshes.push(pad);this.siteMeshes.push(ring,marker);});
  const habitat=new THREE.Group();habitat.name='draggable-habitat-token';const foot=new THREE.Mesh(new THREE.CylinderGeometry(.15,.19,.11,24),new THREE.MeshStandardMaterial({color:'#d3bc84',metalness:.55,roughness:.32}));habitat.add(foot);const dome=new THREE.Mesh(new THREE.SphereGeometry(.13,20,12),new THREE.MeshStandardMaterial({color:'#e6e2d5',metalness:.25,roughness:.28}));dome.position.y=.12;dome.scale.y=.72;habitat.add(dome);habitat.position.set(0,.25,.3);habitat.userData.kind='base';deck.add(habitat);this.interactive.push(habitat);
  const cardX=[-2,-1.07,-.14,.79],cardLabels=['MOON SITES','SPACE WEATHER','LUNAR IMAGE','WATER USE'];cardLabels.forEach((text,i)=>{const g=new THREE.Group();g.position.set(cardX[i],.19,-.82);g.rotation.x=-.16;const card=box(.91,.07,.6,i===0?'#b1a58a':'#9caab0',.66,.14);g.add(card);const face=new THREE.Mesh(new THREE.PlaneGeometry(.8,.39),new THREE.MeshBasicMaterial({map:labelTexture(text,true),toneMapped:false}));face.rotation.x=-Math.PI/2;face.position.y=.04;face.position.z=.005;g.add(face);const pivot=new THREE.Mesh(new THREE.BoxGeometry(.16,.05,.16),new THREE.MeshStandardMaterial({color:'#d6b87c',metalness:.65,roughness:.3}));pivot.position.set(.3,.08,.19);g.add(pivot);g.userData.kind='source';g.userData.index=i;this.interactive.push(g);deck.add(g);});
  // Antenna is an actual movable gimbal with a grippy mast and bearing, not a static icon.
  this.antenna.position.set(1.83,.2,.33);const bearing=new THREE.Mesh(new THREE.CylinderGeometry(.19,.22,.1,32),new THREE.MeshStandardMaterial({color:'#8a928f',metalness:.78,roughness:.27}));this.antenna.add(bearing);const mast=new THREE.Mesh(new THREE.CylinderGeometry(.035,.055,.48,16),new THREE.MeshStandardMaterial({color:'#c2ad7b',metalness:.68,roughness:.32}));mast.position.y=.27;this.antenna.add(mast);const dish=new THREE.Mesh(new THREE.SphereGeometry(.19,24,14,0,Math.PI*2,0,Math.PI/2),new THREE.MeshStandardMaterial({color:'#aebfca',metalness:.68,roughness:.24,side:THREE.DoubleSide}));dish.rotation.x=Math.PI;dish.position.y=.51;this.antenna.add(dish);const grip=new THREE.Mesh(new THREE.TorusGeometry(.24,.018,8,32),new THREE.MeshStandardMaterial({color:'#d5bd82',metalness:.72,roughness:.28,emissive:'#aa7c2d',emissiveIntensity:.1}));grip.rotation.x=Math.PI/2;grip.position.y=.24;this.antenna.add(grip);this.antenna.userData.kind='antenna';deck.add(this.antenna);this.interactive.push(this.antenna);
  const observationZone=box(.78,.07,.55,'#253e50',.4,.4);observationZone.position.set(1.35,.17,-.55);deck.add(observationZone);['OBSERVE','INFER','NEED DATA'].forEach((txt,i)=>{const tile=new THREE.Mesh(new THREE.BoxGeometry(.66,.13,.35),new THREE.MeshStandardMaterial({color:'#b1b7b3',metalness:.32,roughness:.47,emissive:'#a6762e',emissiveIntensity:.04}));tile.position.set(.56+i*.79,.22,-.47);tile.userData.kind='classification';tile.userData.value=(['observe','infer','unknown'] as const)[i];deck.add(tile);this.interactive.push(tile);const text=new THREE.Mesh(new THREE.PlaneGeometry(.58,.16),new THREE.MeshBasicMaterial({map:labelTexture(txt,true),toneMapped:false,side:THREE.DoubleSide}));text.position.set(.56+i*.79,.291,-.47);text.rotation.x=-Math.PI/2;text.userData.kind='classification';text.userData.value=(['observe','infer','unknown'] as const)[i];deck.add(text);this.interactive.push(text);});
  const ports:[number,number][]=[[-1.15,.25],[-.2,.25],[.75,.25]];const portMeshes:THREE.Mesh[]=[];for(const [x,z] of ports){const p=new THREE.Mesh(new THREE.CylinderGeometry(.13,.15,.08,24),new THREE.MeshStandardMaterial({color:'#9ba7a9',metalness:.7,roughness:.3}));p.position.set(x,.17,z);p.userData.kind='port';p.userData.index=portMeshes.length;deck.add(p);portMeshes.push(p);const marker=new THREE.Mesh(new THREE.TorusGeometry(.14,.018,8,32),new THREE.MeshStandardMaterial({color:'#d0b77e',metalness:.7,roughness:.25}));marker.rotation.x=Math.PI/2;marker.position.set(x,.22,z);marker.userData.kind='port';marker.userData.index=portMeshes.length-1;deck.add(marker);}
  this.cable=new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3([new THREE.Vector3(-1.15,.27,.25),new THREE.Vector3(-.68,.4,.25),new THREE.Vector3(-.2,.27,.25)]),24,.025,8,false),new THREE.MeshStandardMaterial({color:'#b0c8d1',metalness:.4,roughness:.42,emissive:'#5c9bb1',emissiveIntensity:.3}));deck.add(this.cable);this.interactive.push(...portMeshes);this.interactive.push(...this.siteMeshes);
  // A compact readout is a shallow scene display, backed by regular HUD text for accessibility.
